func (this *Accessible) Internal_accessibilityActionDescription(action *cocoa.NSString, childID int32) *cocoa.Id {
	var returnValue *cocoa.NSString = cocoa.NSStringString()
	var actionName string = action.GetString()
	if this.AccessibleActionListenersSize() > 0 {
		var event *AccessibleActionEvent = NewAccessibleActionEvent(this)
		for i := int32(0); i < this.AccessibleActionListenersSize(); i++ {
			var listener AccessibleActionListener = jrt.Cast[AccessibleActionListener](this.accessibleActionListeners.Get(i))
			listener.GetActionCount(event)
		}
		var index int32 = -1
		for i := int32(0); i < event.Count; i++ {
			event.Index = i
			for j := int32(0); j < this.AccessibleActionListenersSize(); j++ {
				var listener AccessibleActionListener = jrt.Cast[AccessibleActionListener](this.accessibleActionListeners.Get(j))
				listener.GetName(event)
			}
			if actionName == event.Result {
				index = i
				break
			}
		}
		if index != -1 {
			event.Index = index
			event.Result = ""
			for i := int32(0); i < this.AccessibleActionListenersSize(); i++ {
				var listener AccessibleActionListener = jrt.Cast[AccessibleActionListener](this.accessibleActionListeners.Get(i))
				listener.GetDescription(event)
			}
			if event.Result != "" {
				returnValue = cocoa.NSStringStringWith(event.Result)
			}
		}
	}
	return upcastcocoaNSStringTococoaId(returnValue)
}

func (this *Accessible) Internal_accessibilityActionNames(childID int32) *cocoa.NSArray {
	if this.AccessibleActionListenersSize() > 0 {
		var event *AccessibleActionEvent = NewAccessibleActionEvent(this)
		for i := int32(0); i < this.AccessibleActionListenersSize(); i++ {
			var listener AccessibleActionListener = jrt.Cast[AccessibleActionListener](this.accessibleActionListeners.Get(i))
			listener.GetActionCount(event)
		}
		var array *cocoa.NSMutableArray = cocoa.NSMutableArrayArrayWithCapacity(int64(event.Count))
		for i := int32(0); i < event.Count; i++ {
			event.Index = i
			for j := int32(0); j < this.AccessibleActionListenersSize(); j++ {
				var listener AccessibleActionListener = jrt.Cast[AccessibleActionListener](this.accessibleActionListeners.Get(j))
				listener.GetName(event)
			}
			array.AddObject(upcastcocoaNSStringTococoaId(cocoa.NSStringStringWith(event.Result)))
		}
		return upcastcocoaNSMutableArrayTococoaNSArray(array)
	} else {
		var event *AccessibleControlEvent = NewAccessibleControlEvent(this)
		event.ChildID = childID
		event.Detail = -1
		for i := int32(0); i < this.AccessibleControlListenersSize(); i++ {
			var listener AccessibleControlListener = jrt.Cast[AccessibleControlListener](this.accessibleControlListeners.Get(i))
			listener.GetRole(event)
		}
		if event.Detail == -1 {
			return nil
		}
		this.CheckRole(event.Detail)
		if (childID == ACCCHILDID_SELF) && (this.actionNames != (nil)) {
			return AccessibleRetainedAutoreleased(upcastcocoaNSMutableArrayTococoaNSArray(this.actionNames))
		}
		var returnValue *cocoa.NSMutableArray = cocoa.NSMutableArrayArrayWithCapacity(int64(5))
		switch event.Detail {
		case ACCROLE_PUSHBUTTON, ACCROLE_RADIOBUTTON, ACCROLE_CHECKBUTTON, ACCROLE_TABITEM, ACCROLE_LINK, ACCROLE_CHECKMENUITEM, ACCROLE_RADIOMENUITEM, ACCROLE_SPLITBUTTON:
			returnValue.AddObject(upcastcocoaNSStringTococoaId(cocoa.OSNSAccessibilityPressAction_))
			break
		case ACCROLE_COMBOBOX:
			returnValue.AddObject(upcastcocoaNSStringTococoaId(cocoa.OSNSAccessibilityConfirmAction_))
			break
		case ACCROLE_WINDOW, ACCROLE_DIALOG:
			break
		}
		if childID == ACCCHILDID_SELF {
			this.actionNames = returnValue
			this.actionNames.Retain()
			return AccessibleRetainedAutoreleased(upcastcocoaNSMutableArrayTococoaNSArray(this.actionNames))
		} else {
			return upcastcocoaNSMutableArrayTococoaNSArray(returnValue)
		}
	}
}

func (this *Accessible) Internal_accessibilityIsAttributeSettable(attribute *cocoa.NSString, childID int32) bool {
	if this.AccessibleTextExtendedListenersSize() > 0 {
		if attribute.IsEqualToString(cocoa.OSNSAccessibilitySelectedTextRangeAttribute_) {
			return true
		}
		if attribute.IsEqualToString(cocoa.OSNSAccessibilityVisibleCharacterRangeAttribute_) {
			return true
		}
	}
	if this.AccessibleEditableTextListenersSize() > 0 {
		if attribute.IsEqualToString(cocoa.OSNSAccessibilitySelectedTextAttribute_) {
			return true
		}
	}
	if this.AccessibleValueListenersSize() > 0 {
		if attribute.IsEqualToString(cocoa.OSNSAccessibilityValueAttribute_) {
			return true
		}
	}
	return false
}

